// Register direct-to-provider AI usage with core-guardian so it shows up in spend.
// See https://core-guardian.hacolby.workers.dev/openapi.json
export async function registerGuardianUsage(env, usage) {
  await fetch("https://core-guardian.hacolby.workers.dev/api/guardian/usage/register", {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Authorization: `Bearer ${await env.WORKER_API_KEY.get()}`, // secrets-store binding
    },
    // { worker, provider, model, tokensIn?, tokensOut?, tokensThinking?, requests?,
    //   costUsd?, gateway?, operationId?, taskDescription? }  (worker/provider/model required)
    body: JSON.stringify(usage),
  });
}

