// tokens.ts — import wherever a local script needs Cloudflare creds.
import { execFileSync } from "node:child_process";

export function getSecret(name: string): string {
  return execFileSync("tokens", ["show", name, "--value-only"], { encoding: "utf8" }).trim();
}
export const getCloudflareAccountId = () => getSecret("CLOUDFLARE_ACCOUNT_ID");
export const getCloudflareAiGatewayToken = () => getSecret("CLOUDFLARE_AI_GATEWAY_TOKEN");

