# tokens.py — import wherever a local script needs Cloudflare creds.
import subprocess

def get_secret(name: str) -> str:
    return subprocess.run(
        ["tokens", "show", name, "--value-only"],
        capture_output=True, text=True, check=True,
    ).stdout.strip()

def get_cloudflare_account_id() -> str:
    return get_secret("CLOUDFLARE_ACCOUNT_ID")

def get_cloudflare_ai_gateway_token() -> str:
    return get_secret("CLOUDFLARE_AI_GATEWAY_TOKEN")
